const body = $input.first().json.text || '';
const subject = $input.first().json.subject || '';
const fromObj = $input.first().json.from;
const from = fromObj && fromObj.value && fromObj.value[0] 
  ? fromObj.value[0].address 
  : '';

const subjectLower = subject.toLowerCase();
const fromLower = from.toLowerCase();

const autoReplyPhrases = [
  'out of office',
  'delivery failed',
  'undeliverable',
  'mailer-daemon',
  'automatic reply',
  'auto-reply',
  'auto reply'
];

const isAutoReply = autoReplyPhrases.some(phrase => subjectLower.includes(phrase));
const isNoReplyAddress = fromLower.includes('noreply') || 
                         fromLower.includes('no-reply') || 
                         fromLower.includes('mailer-daemon');
const isTooShort = body.trim().length < 10;

if (isTooShort || isAutoReply || isNoReplyAddress) {
  return [];
}

const cleanBody = body.length > 3000 ? body.substring(0, 3000) : body;

return [{
  json: {
    email_body: cleanBody,
    email_from: from,
    email_subject: subject,
    was_truncated: body.length > 3000
  }
}];

// El LLM devuelve un string — puede venir con ```json ``` o limpio
let rawText = $json.text || $json.output || '';

// Limpiar markdown si el modelo lo agregó igual
rawText = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

// Parsear
let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  throw new Error('LLM Call 1 devolvió JSON inválido: ' + rawText.substring(0, 200));
}

// Validar estructura mínima
if (!parsed.issues || !Array.isArray(parsed.issues) || parsed.issues.length === 0) {
  throw new Error('No se detectaron issues en el ticket');
}

// Devolver un item por issue, con client_data adjunto en cada uno
return parsed.issues.map(issue => ({
  json: {
    client_data: parsed.client_data,
    issue: issue.issue,
    user_intent: issue.user_intent,
    key_entities: issue.key_entities
  }
}));

let rawText = $json.text || $json.output || '';

// Limpiar markdown
rawText = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

// Parsear
let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  throw new Error('LLM Call 2 devolvió JSON inválido: ' + rawText.substring(0, 200));
}

// Validar campos requeridos
const validCategories = ['billing', 'technical', 'account', 'general'];
const validPriorities = ['high', 'medium', 'low'];
const validUrgencies = ['immediate', 'normal', 'low'];
const validActionTypes = ['automatic', 'manual', 'escalation'];
const validTeams = ['support', 'finance', 'engineering'];

const errors = [];

if (!validCategories.includes(parsed.category)) errors.push('category inválido');
if (!validPriorities.includes(parsed.priority)) errors.push('priority inválido');
if (!validUrgencies.includes(parsed.urgency)) errors.push('urgency inválido');
if (!validActionTypes.includes(parsed.action_type)) errors.push('action_type inválido');
if (!validTeams.includes(parsed.target_team)) errors.push('target_team inválido');
if (!parsed.summary || parsed.summary.trim() === '') errors.push('summary vacío');
if (!parsed.recommended_action || parsed.recommended_action.trim() === '') errors.push('recommended_action vacío');
if (!parsed.customer_response || parsed.customer_response.trim() === '') errors.push('customer_response vacío');

if (errors.length > 0) {
  throw new Error('Validación fallida: ' + errors.join(', '));
}

// Devolver issue procesado con client_data adjunto
return [{
  json: {
    client_data: $('Loop - Process Issues').item.json.client_data,
    issue: $('Loop - Process Issues').item.json.issue,
    category: parsed.category,
    priority: parsed.priority,
    reason: parsed.reason,
    summary: parsed.summary,
    recommended_action: parsed.recommended_action,
    fallback_action: parsed.fallback_action,
    action_type: parsed.action_type,
    target_team: parsed.target_team,
    urgency: parsed.urgency,
    customer_response: parsed.customer_response,
    confidence: parsed.confidence
  }
}];

const items = $input.all();

// Array que recibe el Final Composer
const responsesForComposer = items.map(item => ({
  priority: item.json.priority,
  customer_response: item.json.customer_response
}));

// Array completo para guardar en Supabase
const allIssues = items.map(item => ({
  issue: item.json.issue,
  category: item.json.category,
  priority: item.json.priority,
  reason: item.json.reason,
  summary: item.json.summary,
  recommended_action: item.json.recommended_action,
  fallback_action: item.json.fallback_action,
  action_type: item.json.action_type,
  target_team: item.json.target_team,
  urgency: item.json.urgency,
  customer_response: item.json.customer_response,
  confidence: item.json.confidence
}));

// client_data es igual en todos los items, tomamos del primero
const clientData = items[0].json.client_data;

return [{
  json: {
    client_data: clientData,
    issues: allIssues,
    responses_for_composer: JSON.stringify(responsesForComposer)
  }
}];

let rawText = $json.text || $json.output || '';
rawText = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  throw new Error('LLM Call 3 devolvió JSON inválido: ' + rawText.substring(0, 200));
}

if (!parsed.final_response || parsed.final_response.trim() === '') {
  throw new Error('final_response vacío');
}

// client_data: lo tomamos del primer item del Parse + Split Issues
// (es igual en todos los items — viene del mismo ticket)
const clientData = $('Parse + Split Issues').first().json.client_data;

// issues: array completo del Aggregate
const issues = $('Aggregate Issues').first().json.issues;

return [{
  json: {
    client_data: clientData,
    issues: issues,
    final_response: parsed.final_response,
    approval_token: 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
      const r = Math.random() * 16 | 0;
      return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    })
  }
}];
